INSERT INTO products (category_id, name, slug, normalized_name, brand, brand_recognition, verdict, score, summary, pros, cons, specs, price_tier, release_year, status) VALUES
((SELECT id FROM categories WHERE slug = 'gry'), 'Wiedźmin 3: Dziki Gon', 'wiedzmin-3-dziki-gon', 'wiedzmin 3 dziki gon', 'CD Projekt Red', 'mainstream', 'Wydana przez CD Projekt Red, Wiedźmin 3: Dziki Gon to RPG i gra przygodowa na PC, PlayStation, Xbox i Nintendo. Największym atutem jest tu fabuła i klimat.', 7.3, 'To czysto solowe doświadczenie - najlepsze we własnym tempie, bez potrzeby kogoś do grania. Pod względem długości to rozbudowana zawartość na dziesiątki godzin (albo i więcej). Struktura otwartego świata zachęca do schodzenia z głównej ścieżki. Szeroka dostępność platformowa - duża szansa, że zagrasz na tym, co już masz.', '["Historia, która naprawdę wciąga od początku do końca", "Bardzo dobra oprawa wizualna, czasem wręcz popisowa", "Dostępna na PC, PlayStation, Xbox i Nintendo - duży wybór sprzętu do grania"]'::jsonb, '["Spore zaangażowanie czasowe - trudno ukończyć na kilka wieczorów", "Warto sprawdzić krótki fragment rozgrywki przed zakupem, żeby ocenić klimat na własną rękę", "Konkurencja w gatunku (RPG i gra przygodowa) jest spora - warto porównać z podobnymi tytułami"]'::jsonb, '{"platformy": ["PC", "PlayStation", "Xbox", "Nintendo"], "tryb": "solo", "gatunki": ["RPG", "Przygodowa"], "produkcja": "AAA", "dlugosc": "dluga", "fabula_score": 5, "grafika_score": 5, "release_month": 5, "wybor_trudnosci": true, "klimat": "mroczny", "open_world": "otwarty"}'::jsonb, 'sredni', 2015, 'published'),
((SELECT id FROM categories WHERE slug = 'gry'), 'Cyberpunk 2077', 'cyberpunk-2077', 'cyberpunk 2077', 'CD Projekt Red', 'mainstream', 'Cyberpunk 2077 to RPG i gra akcji dostępna na PC, PlayStation i Xbox. Największym atutem jest tu fabuła i klimat.', 6.0, 'To czysto solowe doświadczenie - najlepsze we własnym tempie, bez potrzeby kogoś do grania. Pod względem długości to rozbudowana zawartość na dziesiątki godzin (albo i więcej). Struktura otwartego świata zachęca do schodzenia z głównej ścieżki.', '["Historia, która naprawdę wciąga od początku do końca", "Bardzo dobra oprawa wizualna, czasem wręcz popisowa", "Możliwość dopasowania poziomu trudności do własnych umiejętności"]'::jsonb, '["Spore zaangażowanie czasowe - trudno ukończyć na kilka wieczorów", "Warto sprawdzić krótki fragment rozgrywki przed zakupem, żeby ocenić klimat na własną rękę", "Konkurencja w gatunku (RPG i gra akcji) jest spora - warto porównać z podobnymi tytułami"]'::jsonb, '{"platformy": ["PC", "PlayStation", "Xbox"], "tryb": "solo", "gatunki": ["RPG", "Akcja"], "produkcja": "AAA", "dlugosc": "dluga", "fabula_score": 5, "grafika_score": 5, "release_month": 12, "wybor_trudnosci": true, "klimat": "mroczny", "open_world": "otwarty"}'::jsonb, 'sredni', 2020, 'published'),
((SELECT id FROM categories WHERE slug = 'gry'), 'Red Dead Redemption 2', 'red-dead-redemption-2', 'red dead redemption 2', 'Rockstar Games', 'mainstream', 'Wydana przez Rockstar Games, Red Dead Redemption 2 to gra akcji i gra przygodowa na PC, PlayStation i Xbox. Gra stawia przede wszystkim na historię i narrację.', 5.3, 'Czysto solowe doświadczenie - najlepsze we własnym tempie, bez potrzeby kogoś do grania. Licząc całość zawartości, to rozbudowana zawartość na dziesiątki godzin (albo i więcej). Otwarty świat daje sporo swobody w eksploracji, we własnym tempie.', '["Mocna, zapadająca w pamięć fabuła i klimat", "Grafika i prezentacja na wysokim poziomie", "Możliwość dopasowania poziomu trudności do własnych umiejętności"]'::jsonb, '["Spore zaangażowanie czasowe - trudno ukończyć na kilka wieczorów", "Warto sprawdzić krótki fragment rozgrywki przed zakupem, żeby ocenić klimat na własną rękę", "Konkurencja w gatunku (gra akcji i gra przygodowa) jest spora - warto porównać z podobnymi tytułami"]'::jsonb, '{"platformy": ["PC", "PlayStation", "Xbox"], "tryb": "solo", "gatunki": ["Akcja", "Przygodowa"], "produkcja": "AAA", "dlugosc": "dluga", "fabula_score": 5, "grafika_score": 5, "release_month": 10, "wybor_trudnosci": true, "klimat": "mroczny", "open_world": "otwarty"}'::jsonb, 'sredni', 2018, 'published'),
((SELECT id FROM categories WHERE slug = 'gry'), 'Grand Theft Auto V', 'grand-theft-auto-v', 'grand theft auto v', 'Rockstar Games', 'mainstream', 'Wydana przez Rockstar Games, Grand Theft Auto V to gra akcji na PC, PlayStation i Xbox. Gra stawia przede wszystkim na historię i narrację.', 6.0, 'Da się grać solo, ale naprawdę rozkwita w towarzystwie albo online. Licząc całość zawartości, to rozbudowana zawartość na dziesiątki godzin (albo i więcej). Otwarty świat daje sporo swobody w eksploracji, we własnym tempie. Niska bariera wejścia cenowego - łatwo spróbować na własną rękę.', '["Mocna, zapadająca w pamięć fabuła i klimat", "Grafika i prezentacja na wysokim poziomie", "Bardzo przystępna cena - niskie ryzyko przy wypróbowaniu"]'::jsonb, '["Spore zaangażowanie czasowe - trudno ukończyć na kilka wieczorów", "Warto sprawdzić krótki fragment rozgrywki przed zakupem, żeby ocenić klimat na własną rękę", "Konkurencja w gatunku (gra akcji) jest spora - warto porównać z podobnymi tytułami"]'::jsonb, '{"platformy": ["PC", "PlayStation", "Xbox"], "tryb": "oba", "gatunki": ["Akcja"], "produkcja": "AAA", "dlugosc": "dluga", "fabula_score": 4, "grafika_score": 4, "release_month": 9, "wybor_trudnosci": true, "klimat": "mroczny", "open_world": "otwarty"}'::jsonb, 'budzetowy', 2013, 'published'),
((SELECT id FROM categories WHERE slug = 'gry'), 'Horizon Zero Dawn', 'horizon-zero-dawn', 'horizon zero dawn', 'Guerrilla Games', 'mainstream', 'Horizon Zero Dawn to RPG i gra akcji dostępna na PC i PlayStation. Największym atutem jest oprawa wizualna.', 6.7, 'To czysto solowe doświadczenie - najlepsze we własnym tempie, bez potrzeby kogoś do grania. Pod względem długości to rozbudowana zawartość na dziesiątki godzin (albo i więcej). Struktura otwartego świata zachęca do schodzenia z głównej ścieżki. Bardzo przystępna cena sprawia, że warto dać jej szansę bez większego ryzyka.', '["Historia, która naprawdę wciąga od początku do końca", "Bardzo dobra oprawa wizualna, czasem wręcz popisowa", "Bardzo przystępna cena - niskie ryzyko przy wypróbowaniu"]'::jsonb, '["Ograniczona dostępność platformowa (tylko PC i PlayStation)", "Spore zaangażowanie czasowe - trudno ukończyć na kilka wieczorów", "Warto sprawdzić krótki fragment rozgrywki przed zakupem, żeby ocenić klimat na własną rękę"]'::jsonb, '{"platformy": ["PC", "PlayStation"], "tryb": "solo", "gatunki": ["RPG", "Akcja"], "produkcja": "AAA", "dlugosc": "dluga", "fabula_score": 4, "grafika_score": 5, "release_month": 2, "wybor_trudnosci": true, "klimat": "lekki", "open_world": "otwarty"}'::jsonb, 'budzetowy', 2017, 'published'),
